/* The remote is designed in em (1em = 16px = natural size 10.6 x 30 em) and grows with the
   widget (aspect ratio kept), but never gets smaller than the natural size (scrolls then).
   .fb-box is the size container: font-size of .fb = the em, min() of the fit by width / height. */

.fb-box {
   container-type: size;
   width: 100%;
   height: 100%;
   min-height: 480px;
   display: flex;
   align-items: center;
   justify-content: center;
}
.fb {
   --fb-body: #1d1e20;
   --fb-key: #2c2d30;
   --fb-key-hi: #3a3b3f;
   --fb-text: #d8d8d8;
   font-size: 16px;
   font-size: max(16px, min(calc(100cqw / 10.625), calc(100cqh / 30)));
   flex: none;
   width: 10.625em;
   padding: 0.875em 0.75em 1em;
   box-sizing: border-box;
   display: flex;
   flex-direction: column;
   align-items: center;
   gap: 0.875em;
   border-radius: 2.125em;
   background: linear-gradient(180deg, #2a2b2e 0%, var(--fb-body) 18%, var(--fb-body) 100%);
   box-shadow: inset 0 0.0625em 0 #ffffff14, 0 0.25em 0.875em #0008;
   color: var(--fb-text);
   user-select: none;
}
.fb button {
   border: 0;
   padding: 0;
   font: inherit;
   color: inherit;
   cursor: pointer;
   -webkit-tap-highlight-color: transparent;
}
.fb button:active {
   filter: brightness(1.6);
   transform: scale(0.94);
}
.fb .mdi {
   font-size: 1.3em;
   line-height: 1;
}
.fb-top {
   width: 100%;
   display: flex;
   align-items: center;
   justify-content: space-between;
   padding: 0 0.375em;
   box-sizing: border-box;
}
.fb-power {
   width: 2.125em;
   height: 2.125em;
   border-radius: 50%;
   background: var(--fb-key);
}
.fb.on .fb-power {
   color: #4caf50;
   box-shadow: 0 0 0.5em #4caf5066;
}
.fb.off .fb-power {
   color: #e53935;
}
.fb-mic {
   width: 0.3125em;
   height: 0.3125em;
   border-radius: 50%;
   background: #000;
   box-shadow: 0 0 0 0.125em #333;
}
.fb-btn {
   width: 2.375em;
   height: 2.375em;
   border-radius: 50%;
   background: var(--fb-key);
}
.fb-small {
   width: 1.875em;
   height: 1.875em;
}
.fb-small .mdi {
   font-size: 1.05em;
}
.fb-dpad {
   position: relative;
   width: 8em;
   height: 8em;
   border-radius: 50%;
   background: radial-gradient(circle, var(--fb-key-hi) 0%, var(--fb-key) 70%);
   box-shadow: inset 0 0 0 0.0625em #ffffff10, 0 0.125em 0.25em #0006;
}
.fb-dir {
   position: absolute;
   width: 2.5em;
   height: 2.5em;
   background: transparent;
   border-radius: 50%;
}
.fb-dir .mdi {
   font-size: 1.5em;
   opacity: 0.75;
}
.fb-up    { top: 0.125em;    left: 2.75em; }
.fb-down  { bottom: 0.125em; left: 2.75em; }
.fb-left  { left: 0.125em;   top: 2.75em; }
.fb-right { right: 0.125em;  top: 2.75em; }
.fb-ok {
   position: absolute;
   left: 2.25em;
   top: 2.25em;
   width: 3.5em;
   height: 3.5em;
   border-radius: 50%;
   background: var(--fb-body);
   box-shadow: inset 0 0.0625em 0.125em #000a, 0 0 0 0.0625em #ffffff12;
}
.fb-row {
   display: flex;
   align-items: center;
   gap: 0.625em;
}
.fb-pp {
   display: flex;
   border-radius: 1.1875em;
   overflow: hidden;
   background: var(--fb-key);
}
.fb-pp button {
   width: 1.625em;
   height: 2.375em;
   background: transparent;
}
.fb-pp button + button {
   border-left: 0.0625em solid #ffffff12;
}
.fb-pp .mdi {
   font-size: 1.05em;
}
.fb-rockers {
   display: flex;
   gap: 1em;
}
.fb-rocker {
   display: flex;
   flex-direction: column;
   width: 2.75em;
   border-radius: 1.375em;
   overflow: hidden;
   background: var(--fb-key);
   box-shadow: 0 0.125em 0.25em #0006;
}
.fb-rocker button {
   height: 2.375em;
   background: transparent;
}
.fb-rocker .fb-label {
   height: 2.125em;
   display: flex;
   flex-direction: column;
   align-items: center;
   justify-content: center;
   gap: 0.0625em;
   font-size: 0.75em;
   letter-spacing: 0.0625em;
   opacity: 0.8;
}
.fb-rocker .fb-label .mdi {
   font-size: 1.15em;
}
.fb-rocker .fb-label.muted {
   color: #e53935;
   opacity: 1;
}
.fb-vol {
   font-size: 0.9em;
}
.fb-apps {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 0.375em;
   width: 100%;
}
.fb-app {
   height: 1.5em;
   border-radius: 0.375em;
   font-size: 0.72em !important;
   font-weight: bold;
   white-space: nowrap;
   overflow: hidden;
   opacity: 0.85;
}
.fb-app .mdi {
   font-size: 1.1em;
   vertical-align: middle;
}
.fb-app.aktiv {
   opacity: 1;
   box-shadow: 0 0 0 0.125em #fff;
}
.fb-netflix { background: #141414; color: #e50914 !important; letter-spacing: 0.0625em; }
.fb-prime   { background: #00a8e1; color: #fff !important; }
.fb-youtube { background: #fff; color: #222 !important; }
.fb-youtube .mdi { color: #ff0000; }
.fb-disney  { background: #0e1a5c; color: #fff !important; }
.fb-name {
   font-size: 0.7em;
   line-height: 1.2;
   letter-spacing: 0.125em;
   text-transform: uppercase;
   opacity: 0.45;
}
